// Làm mượt vị trí khi đứng yên: lấy trung bình có trọng số (điểm sai số nhỏ nặng hơn) các lần đo trong 20 giây, bỏ điểm nhảy bất thường; đang di chuyển thì dùng vị trí mới nhất
function locSmooth(p){
  const c = p.coords, now = p.timestamp || Date.now(), acc = Math.max(c.accuracy || 30, 3);
  const moving = (c.speed || 0) > 1.2;
  const B = LOC.buf || (LOC.buf = []);
  if (moving) B.length = 0;
  B.push({x:c.longitude, y:c.latitude, a:acc, t:now});
  while (B.length > 1 && now - B[0].t > 20000) B.shift();
  const avg = L => { let sw = 0, sx = 0, sy = 0; L.forEach(b => { const w = 1 / (b.a * b.a); sw += w; sx += b.x * w; sy += b.y * w; }); return [sx / sw, sy / sw, sw]; };
  let [x, y, sw] = avg(B);
  const keep = B.filter(b => distM([b.x, b.y], [x, y]) <= Math.max(2.5 * b.a, 8));
  if (keep.length && keep.length < B.length) [x, y, sw] = avg(keep);
  if (B.length > 1 && distM([c.longitude, c.latitude], [x, y]) > Math.max(3 * acc, 40)) { B.length = 0; B.push({x:c.longitude, y:c.latitude, a:acc, t:now}); x = c.longitude; y = c.latitude; sw = 1 / (acc * acc); }   // đổi chỗ thật (xa hẳn) thì đi theo luôn
  return {timestamp:now, coords:{latitude:y, longitude:x, accuracy:Math.max(1 / Math.sqrt(sw), Math.min(acc, 4)), heading:c.heading, speed:c.speed, altitude:c.altitude}};
}
